import{_ as o,l as s,o as e,c as i,v as r,p as l,x as n,d,i as f,S as m}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"Transfusion","description":"","frontmatter":{"title":"Transfusion","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/transfusion.md","filePath":"llm/transfusion.md","lastUpdated":1789023840000}'),h={name:"llm/transfusion.md"};function u(p,a,T,_,c,E){const t=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="transfusion" tabindex="-1">Transfusion <a class="header-anchor" href="#transfusion" aria-label="Permalink to &quot;Transfusion&quot;">​</a></h1><div class="epigraph"><p>不必为图像另开一套网。同一 Transformer 对文本做下一词交叉熵，对图像潜变量做扩散损失，一次前向里两种目标。</p><footer>—— Zhou 等 Transfusion: Predict the Next Token and Diffuse Images with One Multi-Modal Model</footer></div><p><a href="/llm/unified-understanding-generation">上一课</a>用双塔或混合离散目标缝理解与生成。缺口是连续图像与离散文本在同层注意力里共存：文本是词表，图是 <a href="/llm/latent-vae">潜空间 VAE</a> 的 \\(z\\)。Transfusion 把扩散训练塞进语言模型前向。后课蒸馏默认：图像支路仍可能要多步采样。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>纯离散统一（Chameleon）付 VQ 税。纯连续理解（LLaVA）没有像素生成头。若图像用独立扩散模型，权重不共享，谈图与造图的表征会分叉。Transfusion 的序列是文本 token 与噪声潜补丁交错；注意力按模态用因果（文本）或双向（图像块）掩码。损失是 \\(\\mathcal{L}_{\\mathrm{CE}}+\\lambda\\mathcal{L}_{\\mathrm{diff}}\\)。</p><p>这与 <a href="/llm/cfg-image">CFG</a> 兼容：图像位置走扩散采样，文本仍自回归。</p><p><span class="marginnote">掩码设计是正确性来源：图像补丁若对后续文本泄漏未完成的 \\(z_0\\)，训练与推理会不一致。实现必须按论文把图像段设成可双向、对文本因果。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>VAE 编码图像到潜补丁，加噪后当连续嵌入送入 Transformer（线性映到模型维）。文本位置出 logits；图像位置出噪声预测。训练混合纯文本、文生图、图生文。推理：文生图从噪声 \\(z_T\\) 多步更新图像槽，同时可读文本前缀。</p>',9)),(e(),l(m,null,{default:n(()=>[f(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20TXT%5B%22%E6%96%87%E6%9C%AC%20token%22%5D%20--%3E%20TR%5B%22%E5%90%8C%E4%B8%80%20Transformer%22%5D%0A%20%20ZT%5B%22%E5%99%AA%E5%A3%B0%E6%BD%9C%E8%A1%A5%E4%B8%81%22%5D%20--%3E%20TR%0A%20%20TR%20--%3E%20CE%5B%22%E4%B8%8B%E4%B8%80%E8%AF%8D%20CE%22%5D%0A%20%20TR%20--%3E%20DIFF%5B%22%E6%89%A9%E6%95%A3%E6%8D%9F%E5%A4%B1%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>共享层让文本条件直接活在每层键值里，不必另接交叉注意力适配器。扩散损失给连续槽稠密梯度，CE 给离散槽。\\(\\lambda\\) 决定谁主导：过大则语言模型被图像噪声带偏，过小则文生图不收敛。这是统一训练的主旋钮，不是架构点缀。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>多步扩散仍贵。下一课把步数压下去，不改「两种损失可以共存」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Transfusion 在同一 Transformer 里混合 CE 与扩散。</li><li>图像走连续潜补丁，文本走词表。</li><li>注意力掩码必须按模态分因果/双向。</li><li>出处：Zhou 等 Transfusion。</li></ul>',6))])}const B=o(h,[["render",u]]);export{C as __pageData,B as default};
